<script setup>
import { computed } from 'vue'
import router from '../../router';
import { config } from '../../constants';

// VARS
const BACKEND_URL = config.url.BACKEND_URL;

// PROPS
const props = defineProps({
    dr: {
        type: Object,
        required: true,
    },
});

var { id, sourceLogo, source, drEvent } = props.dr;

if (source === 'sumnews.net') {
    sourceLogo = `data:image/png;base64,`
}

const wasVisited = computed(() => {
    const dailyRecapInLocalStorage = JSON.parse(localStorage.getItem('dailyRecaps'));
    // Get the current 'dailyrecapbutton' that was clicked on
    var dailyRecapButton = dailyRecapInLocalStorage.dailyRecapButtons.filter(button => button.id == id)[0];
    // Update the object value
    return dailyRecapButton.wasVisited;
})

// Redirect the user to the correct URI after finding out the first article uuid
async function renderDailyRecap(dailyRecapID, drEvent) {
    setTimeout(async () => {
        await router.push({
            name: 'dailyrecap', params: {
                dailyrecapUUID: dailyRecapID,
                drEvent: drEvent
                // drUri: drUri,
                // articleUUID: articleuuid,
            }
        })
    }, 250);


}
</script>

<template>
    <button class="mycontainer" @click="renderDailyRecap(props.dr.id, props.dr.drEvent)">
        <div class="dailyrecap">
            <div class="logo-container">
                <img class="logo bounce" :alt="source" :src="'data:image/jpeg;base64,' + sourceLogo"
                    v-if="source != 'sumnews.net'">
                <img class="logo bounce" :alt="source" :src="sourceLogo" v-else>
                <div class="shader" :class="{ visited: wasVisited }"></div>
            </div>
        </div>
        <!-- <p class="source-title">{{ source }}</p> -->
    </button>
</template>

<style scoped>
.mycontainer {
    border-radius: var(--border-radius);
    text-align: center;
    width: 60px;
    flex: 0 0 auto;
}

.dailyrecap {
    height: fit-content;
    width: fit-content;
}

.logo-container {
    position: relative;
    width: 60px;
    height: 60px;
}

.logo {
    height: 60px;
    width: 60px;
    border-radius: 10px;
    border: 3px solid black;
    position: relative;
    z-index: 1;
}

.shader {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    border-radius: 10px;
    pointer-events: none;
    z-index: 2;
}

.visited {
    background: rgba(0, 0, 0, 0.4);
}

.source-title {
    font-size: 11px;
    display: -webkit-box;
    -webkit-line-clamp: 1;
    -webkit-box-orient: vertical;
    overflow: hidden;
    color: black;
}
</style>